def get_blocks(tab_name: str) -> list[dict]:
    if tab_name not in OSHIMA_TAB_BLOCKS:
        raise KeyError(f"タブ '{tab_name}' は OSHIMA_TAB_BLOCKS に未登録")
    return OSHIMA_TAB_BLOCKS[tab_name]
